import assert from 'node:assert/strict'
import { test } from 'node:test'
import { PGlite } from '@electric-sql/pglite'
import { migrate } from '../src/migrate.ts'
import { ORDER_HISTORY_SQL } from '../src/orders.ts'

test('order history is served by the customer/created_at index with no sort', async () => {
  const db = new PGlite()
  await migrate(db)
  // Small table: force the planner onto the index so the plan shape is what we check.
  await db.query('SET enable_seqscan = off')
  const sql = ORDER_HISTORY_SQL.replace('$1', '42').replace('$2', '20')
  const { rows } = await db.query(`EXPLAIN ${sql}`)
  const plan = rows.map((r) => Object.values(r)[0]).join('\n')
  assert.match(plan, /orders_customer_id_created_at_idx/)
  assert.doesNotMatch(plan, /Sort/)
})
EOF
