import assert from 'node:assert/strict'
import { test } from 'node:test'
import { PGlite } from '@electric-sql/pglite'
import { migrate } from '../src/migrate.ts'
import { ORDER_HISTORY_SQL } from '../src/orders.ts'

test('order history walks the customer/created_at index and never sorts', async () => {
  const db = new PGlite()
  await migrate(db)
  // Enough rows and statistics for the planner to judge the index on cost, as it would in production.
  await db.query(`INSERT INTO orders (customer_id, total_cents, created_at)
    SELECT (g % 500) + 1, 100, now() - (g || ' minutes')::interval FROM generate_series(1, 50000) g`)
  await db.query('ANALYZE orders')
  const sql = ORDER_HISTORY_SQL.replace('$1', '42').replace('$2', '20')
  const { rows } = await db.query(`EXPLAIN ${sql}`)
  const plan = rows.map((r) => Object.values(r)[0]).join('\n')
  assert.match(plan, /Index Scan using orders_customer_id_created_at_idx/)
  assert.doesNotMatch(plan, /Sort/)
})
EOF
